sys_variable_value.value:
(function execute(inputs, outputs) {
    //relembrando que a gente declara as variáveis que vamos usar aqui no codigo com o input
    outputs.array = inputs.string.toString().split(inputs.separator.toString());
})(inputs, outputs);

